def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value: a :class:`datetime.timedelta` instance
    :return: a string representation of the total number of seconds,
             or ``None`` if ``value`` is ``None``.
    """
    if value is None:
        return None
    try:
        total_seconds = int(value.total_seconds())
    except AttributeError:
        raise TypeError("value must be a datetime.timedelta instance")
    except (OverflowError, ValueError):
        return None
    return str(total_seconds)

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return: ISO formatted string representation of the time, or None if value is None.
    """
    if value is None:
        return None
    try:
        import datetime
        if not isinstance(value, datetime.time):
            raise TypeError(f"Expected datetime.time instance, got {type(value).__name__}")
        # Use isoformat to preserve microseconds and timezone information if present
        return value.isoformat()
    except Exception as exc:
        raise ValueError(f"Error dehydrating time value {value!r}: {exc}") from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    # Basic validation: ensure the object has the expected attributes
    required_attrs = ('lat', 'lon', 'time')
    if not all(hasattr(value, attr) for attr in required_attrs):
        raise TypeError(
            f"Expected a Point instance with attributes {required_attrs}, got {type(value).__name__}"
        )

    # Extract latitude and longitude, converting to float if necessary
    try:
        lat = float(value.lat)
        lon = float(value.lon)
    except (TypeError, ValueError) as exc:
        raise TypeError(f"Point coordinates must be numeric: {exc}") from exc

    # Convert the time attribute to an ISO 8601 string if it supports isoformat
    time_attr = value.time
    if hasattr(time_attr, "isoformat"):
        time_str = time_attr.isoformat()
    else:
        # Fallback: try to convert to string directly
        time_str = str(time_attr)

    return {"lat": lat, "lon": lon, "time": time_str}

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        record = getattr(self, "_record", None)
        if isinstance(record, dict):
            return list(record.keys())
        elif isinstance(record, list):
            names = []
            for item in record:
                if hasattr(item, "name"):
                    names.append(item.name)
                elif isinstance(item, dict) and "name" in item:
                    names.append(item["name"])
            return names
        else:
            return []
    except Exception:
        return []

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Retrieve the mapping of supported handlers from the class.
        # Subclasses may override this attribute.
        handlers = getattr(cls, "PROTOCOL_HANDLERS", {})

        # If a specific protocol version is requested, validate the input
        # and return a dictionary containing that single handler if it
        # exists, otherwise an empty dictionary.
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError(
                    f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
                )
            if len(protocol_version) != 2:
                raise TypeError(
                    "protocol_version tuple must contain exactly two elements (major, minor)"
                )
            return (
                {protocol_version: handlers[protocol_version]}
                if protocol_version in handlers
                else {}
            )

        # No specific version requested – return all supported handlers.
        return dict(handlers)

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Attempt to use a mapping if available
    if hasattr(self, "_index"):
        idx = self._index
        if isinstance(idx, dict):
            try:
                return idx[key]
            except KeyError:
                raise KeyError(f"Key not found: {key!r}")
        # Assume a sequence (list/tuple) of keys
        try:
            return idx.index(key)
        except ValueError:
            raise KeyError(f"Key not found: {key!r}")
    # Fallback: try to find key in self._data if it exists
    if hasattr(self, "_data"):
        try:
            return self._data.index(key)
        except ValueError:
            raise KeyError(f"Key not found: {key!r}")
    raise AttributeError("Neither _index nor _data attribute found to locate key")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Build a list of all values and a mapping from keys to values
    try:
        items = list(self.iteritems())
    except AttributeError:
        raise AttributeError("The object does not support iteritems()")

    all_values = [value for _, value in items]
    key_to_value = {key: value for key, value in items}

    # If no keys are provided, return all values
    if not keys:
        return all_values

    result = []
    for k in keys:
        # Handle integer indices
        if isinstance(k, int):
            try:
                result.append(all_values[k])
            except IndexError:
                raise IndexError(f"Index {k} out of range for values list.")
        # Handle string keys
        elif isinstance(k, six.string_types):
            if k in key_to_value:
                result.append(key_to_value[k])
            else:
                raise KeyError(f"Key '{k}' not found in record.")
        else:
            raise TypeError(f"Key {k!r} must be an int or string.")
    return result

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Ensure the record has the expected attributes
    if not hasattr(self, "_keys") or not hasattr(self, "_values"):
        raise AttributeError("Record object must have '_keys' and '_values' attributes")

    # Build mapping from key to index and index to key
    if isinstance(self._keys, dict):
        key_to_index = self._keys
        index_to_key = {v: k for k, v in self._keys.items()}
    else:
        key_to_index = {k: i for i, k in enumerate(self._keys)}
        index_to_key = {i: k for i, k in enumerate(self._keys)}

    # If no keys specified, return all items
    if not keys:
        return {index_to_key[i]: self._values[i] for i in range(len(self._values))}

    result = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._values):
                raise IndexError(f"Index {key} out of bounds")
            field_name = index_to_key[key]
            result[field_name] = self._values[key]
        elif isinstance(key, str):
            if key in key_to_index:
                idx = key_to_index[key]
                result[key] = self._values[idx]
            else:
                result[key] = None
        else:
            raise TypeError(f"Key {key!r} must be an int or str")
    return result

def pop_u16(self):
    """Remove the last two bytes of data, returning them as a big-endian 16-bit unsigned integer."""
    # Determine the buffer attribute
    buf = getattr(self, 'data', None)
    if buf is None:
        buf = getattr(self, '_data', None)
    if buf is None:
        raise AttributeError("No data buffer found")
    if len(buf) < 2:
        raise ValueError("Not enough data to pop 2 bytes")
    # Extract and remove the last two bytes
    last_two = buf[-2:]
    del buf[-2:]
    return int.from_bytes(last_two, 'big')

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
        """
        Appends a DISCARD message to the output queue.

        :param n: number of records to discard, default = -1 (ALL)
        :param qid: query ID to discard for, default = -1 (last query)
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        """
        # Validate arguments
        if not isinstance(n, int):
            raise TypeError(f"n must be an integer, got {type(n).__name__}")
        if not isinstance(qid, int):
            raise TypeError(f"qid must be an integer, got {type(qid).__name__}")
        if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dict or None")
        if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dict or None")

        # Build the DISCARD message
        message = {
            "type": "DISCARD",
            "n": n,
            "qid": qid
        }
        if dehydration_hooks:
            message["dehydration_hooks"] = dehydration_hooks
        if hydration_hooks:
            message["hydration_hooks"] = hydration_hooks

        # Append the message to the output queue
        try:
            queue = getattr(self, "_output_queue", None)
            if queue is None:
                raise RuntimeError("Output queue is not initialized")
            if hasattr(queue, "put"):
                queue.put(message)
            elif hasattr(queue, "append"):
                queue.append(message)
            else:
                raise RuntimeError("Output queue does not support put or append")
        except Exception as exc:
            raise RuntimeError(f"Failed to enqueue DISCARD message: {exc}") from exc

        # Return a Response object that will handle the result
        # The Response class is assumed to be defined elsewhere in the package.
        return Response(message, **handlers)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate the class name
    if not isinstance(name, str):
        raise TypeError(f"name must be a string, got {type(name).__name__}")
    # Validate fields iterable
    try:
        iter(fields)
    except TypeError:
        raise TypeError(f"fields must be an iterable, got {type(fields).__name__}")
    # Collect and validate field names
    field_names = []
    for f in fields:
        if not isinstance(f, str):
            raise TypeError(f"field name must be a string, got {type(f).__name__}")
        if not f.isidentifier():
            raise TypeError(f"field name must be a valid identifier: {f!r}")
        if f in field_names:
            raise TypeError(f"duplicate field name: {f!r}")
        # Ensure we don't override existing Point attributes
        if hasattr(Point, f):
            raise TypeError(f"field name {f!r} conflicts with existing Point attribute")
        field_names.append(f)
    # Validate srid_map
    if not isinstance(srid_map, dict):
        raise TypeError(f"srid_map must be a dict, got {type(srid_map).__name__}")
    # Prepare the namespace for the new class
    namespace = {"SRID_MAP": srid_map}
    # Create the class first
    cls = type(name, (Point,), namespace)
    # Define __init__ to accept field values
    def __init__(self, *args, **kwargs):
        # Extract field values from kwargs
        field_values = {}
        for f in field_names:
            if f in kwargs:
                field_values[f] = kwargs.pop(f)
        # Call the original Point __init__
        super(cls, self).__init__(*args, **kwargs)
        # Set the field attributes
        for f, v in field_values.items():
            setattr(self, f, v)
    cls.__init__ = __init__
    # Optional: provide a helpful __repr__
    def __repr__(self):
        base = super(cls, self).__repr__()
        field_str = ", ".join(f"{f}={getattr(self, f)!r}" for f in field_names)
        if field_str:
            return f"{base}({field_str})"
        return base
    cls.__repr__ = __repr__
    return cls

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        if not callable(func):
            raise TypeError("decorated object must be callable")
        # Append deprecation note to the function's docstring
        existing_doc = func.__doc__ or ""
        deprecation_note = f"\n\nDeprecated: {message}"
        func.__doc__ = existing_doc + deprecation_note
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    if seq is None:
        return []
    try:
        seq_list = list(seq)
    except TypeError:
        raise TypeError("seq must be a sequence of strings")
    for i, item in enumerate(seq_list):
        if not isinstance(item, str):
            raise TypeError(f"element at index {i} is not a string")
    import hashlib, random as _random
    # Create a deterministic seed from the concatenated sequence
    seed_input = ''.join(seq_list).encode('utf-8')
    seed = int(hashlib.sha256(seed_input).hexdigest(), 16)
    rng = _random.Random(seed)
    shuffled = seq_list[:]
    rng.shuffle(shuffled)
    return shuffled

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not isinstance(ttl, (int, float)) or ttl <= 0:
        raise ValueError("ttl must be a positive number")
    if not callable(timer):
        raise ValueError("timer must be a callable returning a monotonic time")
    if not isinstance(typed, bool):
        raise ValueError("typed must be a boolean")

    def decorator(func):
        cache = OrderedDict()

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Build cache key
            if typed:
                key = (
                    tuple((a, type(a)) for a in args),
                    tuple((k, v, type(v)) for k, v in sorted(kwargs.items())),
                )
            else:
                key = (args, tuple(sorted(kwargs.items())))

            now = timer()
            # Check for cached value
            if key in cache:
                value, expire = cache[key]
                if expire > now:
                    # Move to end to mark as recently used
                    cache.move_to_end(key)
                    return value
                else:
                    # Expired entry
                    del cache[key]

            # Compute new value
            value = func(*args, **kwargs)
            expire = now + ttl
            cache[key] = (value, expire)
            cache.move_to_end(key)

            # Evict least-recently used if over maxsize
            if len(cache) > maxsize:
                cache.popitem(last=False)

            return value

        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        if maxsize <= 0:
            return func
        cache = {}
        freq = {}
        if typed:
            def key_factory(*args, **kwargs):
                return (args,
                        tuple(sorted(kwargs.items())),
                        tuple(type(arg) for arg in args),
                        tuple(type(v) for v in kwargs.values()))
        else:
            def key_factory(*args, **kwargs):
                return (args, tuple(sorted(kwargs.items())))
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = key_factory(*args, **kwargs)
            if key in cache:
                freq[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            freq[key] = 1
            if len(cache) > maxsize:
                min_freq = min(freq.values())
                for k in list(freq):
                    if freq[k] == min_freq:
                        del cache[k]
                        del freq[k]
                        break
            return result
        return wrapper
    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        # Get the first key in insertion order
        first_key = next(iter(self))
    except StopIteration:
        # The container is empty
        raise KeyError('dictionary is empty')
    # Remove the key and return its value
    value = self.pop(first_key)
    return (first_key, value)

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    try:
        return self[key]
    except KeyError:
        try:
            self[key] = default
        except Exception as exc:
            raise ValueError(f"Unable to set default for key {key!r}: {exc}") from exc
        return default

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass
                return v
        return wrapper
    return decorator

def is_file_exist(file_name):
        """
        Check if file name exist.
        :param file_name: File name.
        :type file_name: str
        :return: Return true (exist), false (do not exist, or invalid file name)
        :rtype bool
        """
        if not isinstance(file_name, str) or not file_name:
            return False
        try:
            path = os.path.realpath(file_name)
            return os.path.isfile(path)
        except Exception:
            return False

@classmethod
def _reset_logging(cls):
    """
    Reset
    """
    try:
        root = logging.getLogger()
        # Remove all handlers from the root logger
        for handler in root.handlers[:]:
            root.removeHandler(handler)
        # Reset the root logger level to WARNING
        root.setLevel(logging.WARNING)
        # Reconfigure basic logging to ensure a default handler is present
        logging.basicConfig(level=logging.WARNING)
    except Exception as exc:
        # Attempt to log the exception using the class's logger
        try:
            logging.getLogger(cls.__name__).error("Error resetting logging: %s", exc)
        except Exception:
            # Fallback to printing if logger is unavailable
            print(f"Error resetting logging: {exc}")

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    name = self.__class__.__name__
    for suffix in ('Py', 'Fallback'):
        if name.endswith(suffix):
            name = name[:-len(suffix)]
    return name

def directlyProvidedBy(object): # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        if object is None:
            return tuple()
        # If the object itself declares interfaces, return that
        if hasattr(object, "__provides__"):
            return object.__provides__
        # If the object's class declares interfaces, return that
        cls = getattr(object, "__class__", None)
        if cls and hasattr(cls, "__provides__"):
            return cls.__provides__
        # If the object is a class, check its own __provides__
        if isinstance(object, type) and hasattr(object, "__provides__"):
            return object.__provides__
        # No explicit declaration found; return an empty declaration
        return tuple()
    except Exception:
        # In case of any unexpected error, fall back to an empty declaration
        return tuple()

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            _normalizeargs(v, output)

    return output

def _c_optimizations_ignored(self):
    """The opposite of `_c_optimizations_required`."""
    # Ensure the optimization flag is set to ignored (False)
    try:
        self._optimizations_required = False
    except AttributeError:
        # If the attribute does not exist, create it
        setattr(self, "_optimizations_required", False)

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context dictionary
    self.context = {}

    # Reinitialize bins
    try:
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Preserve the current number of bins if they already exist
            if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
                n_bins = len(self.bins)
                self.bins = [self.initial_value] * n_bins
            else:
                # If bins are not yet defined, create a single bin with the initial value
                self.bins = [self.initial_value]
        else:
            # Fall back to the make_bins method if no initial_value is set
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                raise AttributeError("No method to reinitialize bins (missing 'make_bins').")
    except Exception as exc:
        # In case of any unexpected error, raise a clear exception
        raise RuntimeError(f"Failed to reset histogram bins: {exc}") from exc

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    lines = []
    if header is not None:
        lines.append(str(header))
    for point in self:
        try:
            coord, value = point
        except Exception:
            # If point is not a tuple, treat the whole point as value
            coord, value = None, point
        # Convert coordinate
        if coord is None:
            coord_str = ""
        else:
            try:
                # If coordinate is iterable (e.g., tuple/list), join its parts
                coord_str = separator.join(str(c) for c in coord)
            except TypeError:
                # Not iterable, just convert to string
                coord_str = str(coord)
        # Convert value
        if value is None:
            value_str = ""
        else:
            try:
                # Avoid treating strings as iterable of characters
                if isinstance(value, (str, bytes)):
                    value_str = str(value)
                else:
                    value_str = separator.join(str(v) for v in value)
            except TypeError:
                value_str = str(value)
        # Build line
        if coord_str and value_str:
            line = coord_str + separator + value_str
        elif coord_str:
            line = coord_str
        else:
            line = value_str
        lines.append(line)
    return "\n".join(lines) + ("\n" if lines else "")

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    # Primary source: a dictionary of error indices
    if hasattr(self, "_err_indices") and isinstance(self._err_indices, dict):
        return self._err_indices.get(coord_name, [])
    # Secondary source: an attribute named 'errors' that may contain
    # coordinate-specific error information
    if hasattr(self, "errors"):
        try:
            err_obj = self.errors[coord_name]
            # If the object has an 'indexer' attribute, use it
            if hasattr(err_obj, "indexer"):
                return err_obj.indexer
            # If it has an 'indices' attribute, use that
            if hasattr(err_obj, "indices"):
                return err_obj.indices
            # If it is a numpy array or list, return indices of non-zero entries
            if isinstance(err_obj, (list, tuple, np.ndarray)):
                return np.nonzero(err_obj)[0]
        except Exception:
            pass
    # If no error indices are found, return an empty list
    return []

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # Reject Source sequences outright
        if isinstance(seq, Source):
            return False
        # Direct instance of FillRequest
        if isinstance(seq, FillRequest):
            return True
        # Iterate over sequence to find any FillRequest
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    except TypeError:
        # seq is not iterable
        pass
    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return (
            hasattr(obj, "fill") and
            hasattr(obj, "request") and
            callable(getattr(obj, "fill", None)) and
            callable(getattr(obj, "request", None))
        )
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        run_attr = getattr(obj, 'run', None)
        return callable(run_attr)
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return (hasattr(obj, 'fill') and callable(getattr(obj, 'fill')) and
                hasattr(obj, 'compute') and callable(getattr(obj, 'compute')))
    except Exception:
        return False

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    # Define regex patterns for keys and values
    LABEL_KEY_REGEX = re.compile(r'^[a-zA-Z0-9_.-]+$')
    LABEL_VALUE_REGEX = re.compile(r'^[a-zA-Z0-9_.-]+$')

    errors = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            # Validate key regex
            if not LABEL_KEY_REGEX.match(key):
                errors.append(
                    {key: f"Label key '{key}' does not match the regex {LABEL_KEY_REGEX.pattern}"}
                )

        # Validate value type
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): 'expected string or bytes-like object'})
        else:
            # Validate value regex
            if not LABEL_VALUE_REGEX.match(value):
                errors.append(
                    {value: f"Label value '{value}' does not match the regex {LABEL_VALUE_REGEX.pattern}"}
                )

    if errors:
        raise ValidationError(errors)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    # Ensure we are working with a mapping for the current level
    if not isinstance(last_applied_manifest, dict):
        # If the current level is not a dict, we cannot update it; return early
        return

    for field in observer_schema:
        # Skip if the field is not present in the response
        if field not in response:
            continue

        # If the field is missing in the last_applied_manifest, set it
        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]
            continue

        # If the field exists, we may need to recurse for nested structures
        resp_val = response[field]
        curr_val = last_applied_manifest[field]

        # Recurse into dicts
        if isinstance(resp_val, dict) and isinstance(curr_val, dict):
            try:
                update_last_applied_manifest_dict_from_resp(
                    curr_val, resp_val, resp_val
                )
            except Exception:
                # If the helper fails, fall back to a shallow copy
                last_applied_manifest[field] = resp_val
        # Recurse into lists
        elif isinstance(resp_val, list) and isinstance(curr_val, list):
            try:
                update_last_applied_manifest_list_from_resp(
                    curr_val, resp_val, resp_val
                )
            except Exception:
                last_applied_manifest[field] = resp_val
        # For other types, keep the existing value (do not overwrite)
        else:
            # If the current value is None or empty, replace it
            if curr_val in (None, [], {}):
                last_applied_manifest[field] = resp_val
    # No explicit return needed; the function mutates last_applied_manifest in place.

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if app is None:
        raise ValueError("app must not be None")
    # Default observer schema: only watch the resource name
    default_schema = {"metadata": {"name": {"type": "string"}}}
    # Retrieve existing observer schemas if any
    try:
        observer_schemas = getattr(app.spec, "observer_schema", {})
        if observer_schemas is None:
            observer_schemas = {}
    except AttributeError:
        observer_schemas = {}
    # Iterate over resources in the manifest
    try:
        manifest = getattr(app.spec, "manifest", [])
    except AttributeError:
        manifest = []
    for resource in manifest:
        if not isinstance(resource, dict):
            continue
        kind = resource.get("kind")
        if not kind:
            continue
        # If no custom observer schema for this kind, set the default
        if kind not in observer_schemas:
            observer_schemas[kind] = default_schema
    # Update the application spec with the new observer schemas
    try:
        setattr(app.spec, "observer_schema", observer_schemas)
    except AttributeError:
        # If spec is immutable, raise an informative error
        raise AttributeError("app.spec does not support setting observer_schema")
    return observer_schemas

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False
        if not os.path.isdir(path):
            return False
        # Check for the OCFL root marker
        ocfl_dir = os.path.join(path, '.ocfl')
        if not os.path.isdir(ocfl_dir):
            return False
        # Basic check for a manifest file
        manifest = os.path.join(ocfl_dir, 'manifest.json')
        if not os.path.isfile(manifest):
            return False
        return True
    except Exception:
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    status = getattr(self, 'status', None)
    if status is None:
        return prefix
    if hasattr(status, 'name'):
        status_text = status.name
    else:
        status_text = str(status)
    return f"{prefix}{status_text}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    # Attempt to locate the validation log attribute
    log = getattr(self, 'log', None) or getattr(self, 'validation_log', None) or getattr(self, 'entries', None)
    if log is None:
        return prefix
    # If the log is a single string, just prepend the prefix
    if isinstance(log, str):
        return prefix + log
    # Otherwise, assume an iterable of log entries
    lines = []
    for entry in log:
        try:
            line = str(entry)
        except Exception:
            line = repr(entry)
        lines.append(prefix + line)
    return "\n".join(lines)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Ensure inventory is a dictionary
    if not isinstance(inventory, dict):
        raise TypeError(
            f"Inventory must be a dict, got {type(inventory).__name__}"
        )

    # Determine the specification version to use
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get("type")
        if type_val is not None:
            # If the object defines a list of allowed versions, use it
            allowed = getattr(self, "allowed_versions", None)
            if allowed is not None and type_val in allowed:
                spec_version = type_val
            else:
                # If the type is present but not a recognized spec version,
                # raise an error to avoid silent fallback
                raise ValueError(
                    f"Invalid spec version '{type_val}' found in inventory"
                )

    # Perform validation against the appropriate schema
    try:
        if hasattr(self, "_validate_spec"):
            # Preferred internal validation hook
            self._validate_spec(inventory, spec_version)
        elif hasattr(self, "schema"):
            # Fallback to a generic schema validator if available
            self.schema.validate(inventory)
        else:
            # No validation logic available; silently pass
            pass
    except Exception as exc:
        # Wrap any validation exception with context
        raise ValueError(
            f"Validation failed for spec version '{spec_version}': {exc}"
        ) from exc

    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping filenames to digests")
    if not hasattr(digests_used, "__iter__"):
        raise TypeError("digests_used must be an iterable of digests")
    manifest_digests = set(manifest_files.values())
    used_digests = set(digests_used)
    missing_in_used = manifest_digests - used_digests
    if missing_in_used:
        raise ValueError(f"Digests missing from used set: {', '.join(missing_in_used)}")
    missing_in_manifest = used_digests - manifest_digests
    if missing_in_manifest:
        raise ValueError(f"Used digests not present in manifest: {', '.join(missing_in_manifest)}")
    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity block missing required 'files' key")

    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' entry must be a list")

    # Ensure manifest_files is a set for efficient lookup
    manifest_set = set(manifest_files)

    seen_paths = set()
    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"File entry at index {idx} must be a dictionary")

        if 'path' not in entry:
            raise ValueError(f"File entry at index {idx} missing required 'path' key")
        if 'hash' not in entry:
            raise ValueError(f"File entry at index {idx} missing required 'hash' key")

        path = entry['path']
        hash_val = entry['hash']

        if not isinstance(path, str):
            raise ValueError(f"File path at index {idx} must be a string")
        if not isinstance(hash_val, str):
            raise ValueError(f"Hash for file '{path}' must be a string")

        if path not in manifest_set:
            raise ValueError(f"Fixity references unknown file '{path}'")

        if path in seen_paths:
            raise ValueError(f"Duplicate file reference in fixity block: '{path}'")
        seen_paths.add(path)

def files_list(path):
    """Return the files in `path`"""
    try:
        return [os.path.join(path, f) for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    except OSError:
        return []

def add_asset(self, basename, file_path):
    """
    "{
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """
    # Validate inputs
    if not isinstance(basename, str) or not basename:
        raise ValueError("basename must be a non-empty string")
    if not isinstance(file_path, str) or not file_path:
        raise ValueError("file_path must be a non-empty string")
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"Source file does not exist: {file_path}")

    # Ensure asset directory exists
    dest_dir = getattr(self, "_asset_path", None)
    if dest_dir is None:
        raise AttributeError("Asset manager does not have _asset_path attribute")
    if not os.path.isdir(dest_dir):
        os.makedirs(dest_dir, exist_ok=True)

    # Destination path
    dest_path = os.path.join(dest_dir, basename)

    # Copy file
    try:
        shutil.copy2(file_path, dest_path)
    except Exception as e:
        raise IOError(f"Failed to copy asset to {dest_path}: {e}") from e

    # Update internal mapping if exists
    if hasattr(self, "_assets") and isinstance(self._assets, dict):
        self._assets[basename] = dest_path

    return dest_path

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string path to a zip file")

    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    package_data = {}
    xml_basenames = set()

    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # First pass: identify XML basenames
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                base = os.path.basename(name)
                _, ext = os.path.splitext(base)
                if ext.lower() == '.xml':
                    xml_basenames.add(os.path.splitext(base)[0])

            # Second pass: collect files under each XML basename
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                base = os.path.basename(name)
                key, _ = os.path.splitext(base)
                if key in xml_basenames:
                    if key not in package_data:
                        package_data[key] = {}
                    # Read file content
                    try:
                        content = zf.read(info)
                    except RuntimeError as e:
                        # Skip unreadable files
                        continue
                    package_data[key][name] = content
    except zipfile.BadZipFile as e:
        raise zipfile.BadZipFile(f"Invalid zip file: {zip_path}") from e
    except Exception as e:
        raise RuntimeError(f"Error processing zip file {zip_path}: {e}") from e

    return package_data

def files_list_from_zipfile(zip_path):
    """Return the files in `zip_path`."""
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # Filter out directories and optionally other unwanted files
            files = [name for name in zf.namelist() if not name.endswith('/') and not name.endswith('.pyc')]
            return sorted(files)
    except (FileNotFoundError, zipfile.BadZipFile):
        # If the zip file cannot be opened, return an empty list
        return []

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`"""
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None or not pubdate_xpaths:
        return None
    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
            if matches:
                return matches[0]
        except Exception:
            continue
    return None

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
