def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def wrapper(*args, **kwargs):
        import sys
        result = namefunc(*args, **kwargs)
        if sys.version_info[0] < 3:
            if isinstance(result, unicode):
                return result.encode()
            return result
        return result
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    # Default value if all attempts fail
    default = "unknown"

    # Attempt 1: read a plain VERSION file
    try:
        with open("VERSION", "r") as f:
            return f.read().strip()
    except FileNotFoundError:
        pass
    except Exception:
        return default

    # Attempt 2: read a version.py file and extract the value of the first assignment
    try:
        with open("version.py", "r") as f:
            contents = f.read().strip()
        # Find the first '=' and split
        if "=" in contents:
            _, value = contents.split("=", 1)
            # Strip whitespace and surrounding quotes
            return value.strip().strip('"\'' )
    except Exception:
        return default

    # If all attempts fail, return the default
    return default

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    try:
        # Normalize pieces
        if isinstance(pieces, dict):
            major = pieces.get('major', 0)
            minor = pieces.get('minor', 0)
            patch = pieces.get('patch', 0)
            prerelease = pieces.get('prerelease', '')
            build = pieces.get('build', '')
        elif isinstance(pieces, (list, tuple)):
            if len(pieces) < 3:
                raise ValueError("pieces list must contain at least major, minor, patch")
            major, minor, patch = pieces[0], pieces[1], pieces[2]
            prerelease = pieces[3] if len(pieces) > 3 else ''
            build = pieces[4] if len(pieces) > 4 else ''
        else:
            raise TypeError("pieces must be a dict or list/tuple")

        # Convert numeric parts to int
        try:
            major = int(major)
            minor = int(minor)
            patch = int(patch)
        except Exception as e:
            raise ValueError("major, minor, and patch must be integers") from e

        # Build base version string
        base = f"{major}.{minor}.{patch}"
        if prerelease:
            base += f"-{prerelease}"
        if build:
            base += f"+{build}"

        # Return based on style
        if style == 'semver':
            return base
        elif style == 'short':
            return f"{major}.{minor}"
        elif style == 'full':
            return base
        elif style == 'custom':
            if isinstance(pieces, dict) and 'format' in pieces:
                fmt = pieces['format']
                try:
                    return fmt.format(major=major, minor=minor, patch=patch,
                                      prerelease=prerelease, build=build)
                except Exception as e:
                    raise ValueError("Invalid format string") from e
            else:
                raise ValueError("Custom style requires a 'format' key in pieces")
        else:
            raise ValueError(f"Unsupported style: {style}")

    except Exception as exc:
        raise

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        # If pieces is a string, check directly
        if isinstance(pieces, str):
            return '.' if '+' in pieces else '+'
        # If pieces is an iterable (e.g., list, tuple), check each element
        for item in pieces:
            if item == '+':
                return '.'
        return '+'
    except Exception:
        # In case of invalid input, default to '+'
        return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate and normalise inputs
    if commands is None:
        raise ValueError("commands must not be None")
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a list or tuple of strings")
    if args is None:
        args = []
    if isinstance(args, str):
        args = [args]
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of strings")

    # Build the full command list
    full_cmd = list(commands) + list(args)

    if verbose:
        print("Running command:", " ".join(full_cmd))

    # Prepare environment
    env_vars = os.environ.copy()
    if env:
        env_vars.update(env)

    # Determine stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env_vars,
            stdout=subprocess.PIPE,
            stderr=stderr,
            text=True,
            check=True
        )
        return result.stdout
    except subprocess.CalledProcessError as e:
        msg = f"Command '{' '.join(full_cmd)}' returned non-zero exit status {e.returncode}."
        if e.stdout:
            msg += f"\nStdout: {e.stdout}"
        if e.stderr:
            msg += f"\nStderr: {e.stderr}"
        raise RuntimeError(msg) from e
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {full_cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to run command: {' '.join(full_cmd)}") from e

def register_vcs_handler(vcs, method):  # tyoe: (str, str) -> typing.Callable  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str):
        raise TypeError("vcs must be a string")
    if not isinstance(method, str):
        raise TypeError("method must be a string")
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if not callable(f):
            raise TypeError("decorated object must be callable")
        global HANDLERS
        if 'HANDLERS' not in globals():
            HANDLERS = {}
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError('validate_objects must be a bool')
    if not isinstance(check_digests, bool):
        raise TypeError('check_digests must be a bool')
    if not isinstance(show_warnings, bool):
        raise TypeError('show_warnings must be a bool')

    # If no root defined, nothing to validate
    if not hasattr(self, 'root') or self.root is None:
        return 0, 0

    # Helper to traverse hierarchy; assume it yields objects
    try:
        objects = list(self._traverse_hierarchy(self.root))
    except Exception as exc:
        # If traversal fails, treat as zero objects
        if show_warnings:
            print(f'Warning: failed to traverse hierarchy: {exc}')
        return 0, 0

    num_objects = len(objects)
    good_objects = 0

    for obj in objects:
        is_valid = True
        # Validate object structure if requested
        if validate_objects:
            try:
                # Assume each object has a validate() method returning bool
                is_valid = obj.validate()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f'Warning: validation failed for {obj}: {exc}')

        # Check digest if requested
        if is_valid and check_digests:
            try:
                # Assume object has compute_digest() and digest attributes
                expected = getattr(obj, 'digest', None)
                actual = getattr(obj, 'compute_digest', lambda: None)()
                if expected is not None and actual is not None:
                    if expected != actual:
                        is_valid = False
                        if show_warnings:
                            print(f'Warning: digest mismatch for {obj}')
                else:
                    # If digest info missing, treat as invalid
                    is_valid = False
                    if show_warnings:
                        print(f'Warning: missing digest information for {obj}')
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f'Warning: digest check failed for {obj}: {exc}')

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        return version
    stripped = version.strip()
    if not stripped:
        return version
    try:
        num = int(stripped)
    except ValueError:
        return version
    new_num = num + 1
    width = len(stripped)
    new_str = str(new_num)
    if len(new_str) < width:
        new_str = new_str.zfill(width)
    return new_str

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have a root inventory to compare against
    if hasattr(self, 'root_inventory'):
        root_inventory = self.root_inventory
    elif hasattr(self, 'root_inventory_path'):
        try:
            with open(self.root_inventory_path, 'r', encoding='utf-8') as f:
                root_inventory = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load root inventory: {exc}") from exc
    else:
        raise AttributeError("No root inventory available for comparison")

    # Prepare structures for validation
    seen_files = set()
    self.different_digests = {}

    for idx, version_dir in enumerate(version_dirs, start=1):
        # Build path to the inventory file for this version
        inventory_path = os.path.join(self.base_path, version_dir, 'inventory.json')
        if not os.path.isfile(inventory_path):
            raise ValueError(f"Missing inventory file in version directory '{version_dir}'")

        try:
            with open(inventory_path, 'r', encoding='utf-8') as f:
                inventory = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory from '{inventory_path}': {exc}") from exc

        if not isinstance(inventory, dict):
            raise ValueError(f"Inventory in '{inventory_path}' must be a JSON object")

        # Check that this inventory contains all files seen so far
        missing = seen_files - inventory.keys()
        if missing:
            raise ValueError(
                f"Inventory in '{inventory_path}' is missing files from previous versions: "
                f"{', '.join(sorted(missing))}"
            )

        # Record any digest differences compared to the root inventory
        for file_path, digest in inventory.items():
            root_digest = root_inventory.get(file_path)
            if root_digest is None:
                # File not present in root inventory; skip or record as needed
                continue
            if digest != root_digest:
                self.different_digests.setdefault(file_path, []).append(version_dir)

        # Update the set of seen files for the next iteration
        seen_files.update(inventory.keys())

    return self

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if params is None:
        params = {}
    if bug_ids is None:
        return params
    # Accept a single id or an iterable of ids
    if isinstance(bug_ids, (list, tuple, set)):
        if not bug_ids:
            return params
        ids_str = ','.join(str(bid) for bid in bug_ids)
    elif isinstance(bug_ids, (int, str)):
        ids_str = str(bug_ids)
    else:
        raise ValueError("bug_ids must be an int, str, or an iterable of ids")
    params['ids'] = ids_str
    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode (has a list of key/value pairs)
    def is_mapping_node(node):
        return hasattr(node, 'value') and isinstance(node.value, list)

    # Recursively merge two nodes: if both are mapping nodes, merge their contents;
    # otherwise, the second node wins (last value wins).
    def merge_nodes(node1, node2):
        if is_mapping_node(node1) and is_mapping_node(node2):
            return merge_mapping_nodes(node1, node2)
        return node2

    # Merge two MappingNodes
    def merge_mapping_nodes(node1, node2):
        # Build an ordered mapping from key string to (key_node, value_node)
        merged_items = []
        key_index = {}
        # Start with the items from node1
        for k, v in node1.value:
            key_str = k.value
            key_index[key_str] = len(merged_items)
            merged_items.append((k, v))
        # Merge items from node2
        for k2, v2 in node2.value:
            key_str = k2.value
            if key_str in key_index:
                idx = key_index[key_str]
                existing_key, existing_val = merged_items[idx]
                merged_val = merge_nodes(existing_val, v2)
                merged_items[idx] = (existing_key, merged_val)
            else:
                key_index[key_str] = len(merged_items)
                merged_items.append((k2, v2))
        # Create a new MappingNode with the same tag as node1
        return type(node1)(tag=node1.tag, value=merged_items)

