def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed = {}
    remaining_lists = []

    for name, parser in subparsers.items():
        try:
            namespace, remaining = parser.parse_known_args(unparsed_arguments)
        except Exception:
            # If parsing fails, treat as no arguments claimed
            namespace = None
            remaining = list(unparsed_arguments)
        parsed[name] = namespace
        remaining_lists.append(remaining)

    if not remaining_lists:
        remaining_not_claimed = list(unparsed_arguments)
    else:
        # Compute intersection of all remaining lists
        intersection = set(remaining_lists[0])
        for rem in remaining_lists[1:]:
            intersection &= set(rem)
        # Preserve original order
        remaining_not_claimed = [arg for arg in unparsed_arguments if arg in intersection]

    return parsed, remaining_not_claimed

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate inputs
    if response is None:
        raise ValueError("response cannot be None")
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int):
        raise TypeError("max_results must be an integer")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Return a generator that yields slices of the response
    return (response[i:i + max_results] for i in range(0, len(response), max_results))

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        return {}
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for k, v in d.items():
            try:
                result[k] = result.get(k, 0) + v
            except TypeError as exc:
                raise TypeError(f"Cannot sum values for key '{k}': {exc}") from exc
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    # Validate input
    if not isinstance(url, str):
        return url
    if not url_args:
        return url
    try:
        items = list(url_args.items())
    except AttributeError:
        return url

    result = url
    for key, value in items:
        # Convert key and value to string safely
        key_str = str(key)
        value_str = '' if value is None else str(value)
        placeholder = '{' + key_str + '}'
        # Replace all occurrences of the placeholder
        if placeholder in result:
            result = result.replace(placeholder, value_str)
    return result

