def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two distinct symbols")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        # digits are least significant first, reverse for most significant first
        result = ''.join(reversed(digits))

    # Apply padding if requested
    if padding is not None and len(result) < padding:
        pad_len = padding - len(result)
        result = alphabet[0] * pad_len + result

    return result

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError(f"value must be a string, got {type(value).__name__}")
    if not isinstance(arg, str):
        raise TypeError(f"arg must be a string, got {type(arg).__name__}")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("subclasses() expects a class type")
    seen = set()
    stack = [cls]
    while stack:
        parent = stack.pop()
        for child in parent.__subclasses__():
            if child not in seen:
                seen.add(child)
                stack.append(child)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate input types
    if not isinstance(string, str):
        raise TypeError(f"string must be a str, got {type(string).__name__}")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")

    # Alphabet must contain at least two unique symbols for a valid base
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two unique symbols for a valid base")

    # Ensure all alphabet elements are single-character strings and unique
    seen = set()
    for idx, sym in enumerate(alphabet):
        if not isinstance(sym, str) or len(sym) != 1:
            raise ValueError(f"alphabet element at index {idx} must be a single-character string, got {sym!r}")
        if sym in seen:
            raise ValueError(f"alphabet contains duplicate symbol '{sym}' at index {idx}")
        seen.add(sym)

    base = len(alphabet)
    mapping = {sym: i for i, sym in enumerate(alphabet)}

    # Validate string
    if string == "":
        raise ValueError("string must not be empty")

    result = 0
    for pos, ch in enumerate(string):
        if ch not in mapping:
            raise ValueError(f"character '{ch}' at position {pos} not found in alphabet")
        result = result * base + mapping[ch]

    return result

