    return ','.join(files)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Handle None or "always" (case-insensitive)
    if frequency is None:
        return None
    if isinstance(frequency, str) and frequency.strip().lower() == "always":
        return None

    if not isinstance(frequency, str):
        raise ValueError("Frequency must be a string, None, or 'always'")

    freq = frequency.strip()
    if not freq:
        raise ValueError("Empty frequency string")

    import re
    m = re.match(r'^(\d+)\s*([a-zA-Z]+)$', freq)
    if not m:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    num = int(m.group(1))
    unit = m.group(2).lower()

    if unit in ('day', 'days'):
        return datetime.timedelta(days=num)
    if unit in ('week', 'weeks'):
        return datetime.timedelta(weeks=num)
    if unit in ('hour', 'hours'):
        return datetime.timedelta(hours=num)
    if unit in ('minute', 'minutes'):
        return datetime.timedelta(minutes=num)
    if unit in ('second', 'seconds'):
        return datetime.timedelta(seconds=num)
    if unit in ('month', 'months'):
        # Approximate a month as 30 days
        return datetime.timedelta(days=num * 30)
    if unit in ('year', 'years'):
        # Approximate a year as 365 days
        return datetime.timedelta(days=num * 365)

    raise ValueError(f"Unknown time unit: {unit}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Quick checks for common localhost representations
    if host in ("localhost", "127.0.0.1", "::1"):
        return True

    try:
        # Resolve the host to all possible addresses
        addrinfo = socket.getaddrinfo(host, None, 0, 0, 0, socket.AI_PASSIVE)
    except socket.gaierror:
        # If the host cannot be resolved, it cannot be localhost
        return False

    for family, _, _, _, sockaddr in addrinfo:
        # sockaddr is a tuple; the IP address is the first element
        ip = sockaddr[0]
        if family == socket.AF_INET:
            # IPv4 loopback range is 127.0.0.0/8
            if ip.startswith("127."):
                return True
        elif family == socket.AF_INET6:
            # IPv6 loopback is ::1
            if ip == "::1":
                return True

    return False

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        env = os.environ
        # Common environment variables set by Git Bash
        if env.get('OSTYPE', '').startswith('msys'):
            return True
        if env.get('MSYSTEM', '').startswith('MINGW'):
            return True
        # Check PATH for typical Git Bash directories
        path = env.get('PATH', '').replace('\\', '/').lower()
        if 'git/usr/bin' in path or 'git\\usr\\bin' in path:
            return True
    except Exception:
        # In case of any unexpected error, default to False
        pass
    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    config_filename = os.path.expanduser(config_filename)
    if not overwrite and os.path.isfile(config_filename):
        return
    try:
        dir_name = os.path.dirname(config_filename)
        if dir_name:
            os.makedirs(dir_name, exist_ok=True)
    except OSError:
        if not os.path.isdir(dir_name):
            raise
    try:
        with open(config_filename, 'w') as f:
            f.write(rendered_config)
        os.chmod(config_filename, mode)
    except OSError as e:
        raise e

