def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    # Return None if pattern is None
    if pattern is None:
        return None

    # Determine the type used for compiled regex objects
    try:
        pattern_type = re.Pattern
    except AttributeError:
        pattern_type = type(re.compile(''))

    # If already a compiled regex, return it unchanged
    if isinstance(pattern, pattern_type):
        return pattern

    # If pattern is a string, optionally strip whitespace and compile
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)

    # If pattern is bytes, decode to string before compiling
    if isinstance(pattern, bytes):
        decoded = pattern.decode()
        if strip:
            decoded = decoded.strip()
        return re.compile(decoded)

    # Unsupported type
    raise TypeError(f"Invalid pattern type: {type(pattern).__name__}")

