    except (ValueError, TypeError):
        return False

def make_array(shape, dtype=np.dtype("float32")):
    """Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate shape
    try:
        shape_tuple = tuple(shape)
    except Exception as exc:
        raise TypeError("shape must be an iterable of integers") from exc
    if not all(isinstance(dim, int) and dim >= 0 for dim in shape_tuple):
        raise ValueError("shape must contain non-negative integers")
    # Validate dtype
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise TypeError("dtype must be a valid numpy dtype") from exc
    return np.empty(shape_tuple, dtype=dtype_obj)

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import logging
    configs = {}
    errors = []

    def _expand_env(obj):
        if isinstance(obj, dict):
            return {k: _expand_env(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_expand_env(v) for v in obj]
        if isinstance(obj, str):
            return os.path.expandvars(obj)
        return obj

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                raw = f.read()
            ext = os.path.splitext(fname)[1].lower()
            if ext == '.toml':
                import toml
                cfg = toml.loads(raw)
            elif ext in ('.yaml', '.yml'):
                import yaml
                cfg = yaml.safe_load(raw)
            elif ext == '.json':
                import json
                cfg = json.loads(raw)
            else:
                raise ValueError(f"Unsupported config file extension: {ext}")
            if not isinstance(cfg, dict):
                raise ValueError("Parsed configuration is not a dictionary")
            if overrides:
                cfg.update(overrides)
            if resolve_env:
                cfg = _expand_env(cfg)
            configs[fname] = cfg
        except Exception as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=str(exc),
                args=(),
                exc_info=None
            )
            errors.append(record)
    return configs, errors

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    # If the object is a Python string, encode it to UTF-8 bytes
    if isinstance(obj, str):
        try:
            return obj.encode('utf-8')
        except UnicodeEncodeError as exc:
            raise ValueError("String could not be encoded to UTF-8") from exc
    # For all other types, return the object unchanged
    return obj

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise ValueError("values cannot be None")
    try:
        iter(values)
    except TypeError:
        raise TypeError("values must be an iterable of strings")

    bookmarks = []
    for raw in values:
        if not isinstance(raw, str):
            continue
        try:
            # Try to interpret the raw string as JSON first
            import json
            data = json.loads(raw)
            bookmark = Bookmark(**data)
        except Exception:
            # Fallback: split on a delimiter (e.g., '|')
            parts = raw.split('|')
            if len(parts) >= 3:
                try:
                    bookmark = Bookmark(id=parts[0], title=parts[1], url=parts[2])
                except Exception:
                    continue
            else:
                continue
        bookmarks.append(bookmark)

    # Construct the Bookmarks instance; assume the constructor accepts a list
    try:
        return cls(bookmarks=bookmarks)
    except TypeError:
        # Fallback to positional argument if keyword not accepted
        return cls(bookmarks)

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    # 1. Check that the candidate claims to provide the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                raise zope.interface.Invalid(
                    f"{candidate!r} does not provide {iface!r}"
                )
        except Exception as exc:
            errors.append(exc)

    # 2. Check that all required methods are present and have compatible signatures
    #    iface.methods is a mapping of method names to Method objects
    for name, method in getattr(iface, "methods", {}).items():
        if not hasattr(candidate, name):
            errors.append(
                zope.interface.Invalid(
                    f"{candidate!r} missing method {name!r} required by {iface!r}"
                )
            )
            continue
        cand_method = getattr(candidate, name)
        if not callable(cand_method):
            errors.append(
                zope.interface.Invalid(
                    f"{candidate!r} attribute {name!r} is not callable"
                )
            )
            continue
        # Compare signatures if possible
        try:
            iface_sig = inspect.signature(method)
            cand_sig = inspect.signature(cand_method)
            if iface_sig != cand_sig:
                errors.append(
                    zope.interface.Invalid(
                        f"Signature mismatch for {name!r} in {candidate!r}: "
                        f"expected {iface_sig}, got {cand_sig}"
                    )
                )
        except Exception:
            # If we cannot obtain a signature, skip the check
            pass

    # 3. Check that all required attributes are present
    for name in getattr(iface, "attributes", {}):
        if not hasattr(candidate, name):
            errors.append(
                zope.interface.Invalid(
                    f"{candidate!r} missing attribute {name!r} required by {iface!r}"
                )
            )

    # 4. Raise collected errors or return True
    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            msg = "\n".join(str(e) for e in errors)
            raise zope.interface.Invalid(msg)
    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    if not isinstance(iface, type):
        raise TypeError(f"iface must be a type, got {type(iface).__name__}")
    if candidate is None:
        raise ValueError("candidate cannot be None")
    if not isinstance(tentative, bool):
        raise TypeError(f"tentative must be a bool, got {type(tentative).__name__}")
    provides = False
    try:
        if isinstance(candidate, type):
            provides = issubclass(candidate, iface)
        else:
            provides = isinstance(candidate, iface)
    except Exception:
        provides = False
    if not provides:
        if tentative:
            return False
        else:
            raise TypeError(f"Candidate {candidate!r} does not provide interface {iface.__name__}")
    return True

