def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if not isinstance(dt, datetime):
        raise TypeError("dt must be a datetime instance")
    # Ensure the datetime is timezone-aware and in UTC
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    else:
        dt = dt.astimezone(datetime.timezone.utc)
    # Return ISO 8601 string without microseconds, ending with 'Z'
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        from urllib.parse import urlparse
        from urllib.request import Request, urlopen
        from urllib.error import URLError, HTTPError
    except Exception:
        return None

    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https"):
        return None

    req = Request(url, method="HEAD")
    try:
        with urlopen(req, timeout=10) as resp:
            status = getattr(resp, "status", resp.getcode())
            if status != 200:
                return None
            return resp.headers.get("Content-Type")
    except (HTTPError, URLError):
        return None
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("'tag' expects a string")
    if not tag:
        return False
    # Tag must be 1-30 characters long and contain only letters, digits, hyphens, or underscores
    if len(tag) > 30:
        return False
    import re
    pattern = re.compile(r'^[A-Za-z0-9_-]+$')
    return bool(pattern.match(tag))

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError(f"Expected an ElementTree element, got {type(node).__name__}") from exc

    result = {}
    for child in children:
        tag = child.tag
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if document_path is not None and not isinstance(document_path, str):
        raise TypeError("document_path must be a string if provided")

    # Default path if none supplied
    if document_path is None:
        document_path = "/.well-known/nodeinfo"

    # Ensure the document path starts with a slash
    if not document_path.startswith("/"):
        document_path = "/" + document_path

    # Remove any trailing slash from the base URL
    base = url.rstrip("/")

    href = base + document_path

    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed author did actually generate this message."""
    try:
        if not public_key or not doc:
            return False

        # Parse the XML document
        from lxml import etree
        root = etree.fromstring(doc)

        # Determine the signature node
        sig_node = None
        if signature:
            try:
                sig_node = etree.fromstring(signature)
            except Exception:
                # If signature string cannot be parsed, fall back to searching in doc
                pass

        if sig_node is None:
            ns = {'ds': 'http://www.w3.org/2000/09/xmldsig#'}
            sig_node = root.find('.//ds:Signature', namespaces=ns)

        if sig_node is None:
            return False

        # Load the public key and verify
        import xmlsec
        key = xmlsec.Key.from_file(public_key, xmlsec.KeyFormat.PEM)
        ctx = xmlsec.SignatureContext()
        ctx.key = key

        # Register Id attributes to allow reference resolution
        for attr in ('Id', 'id', 'ID'):
            ctx.register_id(root, attr)
            ctx.register_id(sig_node, attr)

        ctx.verify(sig_node)
        return True
    except Exception:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        data = json.loads(document)
        subject = data.get("subject")
        aliases = data.get("aliases", [])
        hcard_url = None
        lrdd_url = None
        for link in data.get("links", []):
            rel = link.get("rel")
            if rel == "hcard":
                hcard_url = link.get("href")
            elif rel == "lrdd":
                lrdd_url = link.get("template")
        return {
            "subject": subject,
            "aliases": aliases,
            "hcard_url": hcard_url,
            "lrdd_url": lrdd_url,
        }
    except Exception:
        pass

    # Try XML (XRD) with namespace
    try:
        root = ET.fromstring(document)
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        subject_elem = root.find("xrd:Subject", ns)
        subject = subject_elem.text if subject_elem is not None else None
        aliases = [a.text for a in root.findall("xrd:Alias", ns)]
        hcard_url = None
        lrdd_url = None
        for link in root.findall("xrd:Link", ns):
            rel = link.attrib.get("rel")
            if rel == "hcard":
                hcard_url = link.attrib.get("href")
            elif rel == "lrdd":
                lrdd_url = link.attrib.get("template")
        return {
            "subject": subject,
            "aliases": aliases,
            "hcard_url": hcard_url,
            "lrdd_url": lrdd_url,
        }
    except Exception:
        pass

    # Try XML without namespace
    try:
        root = ET.fromstring(document)
        subject_elem = root.find("Subject")
        subject = subject_elem.text if subject_elem is not None else None
        aliases = [a.text for a in root.findall("Alias")]
        hcard_url = None
        lrdd_url = None
        for link in root.findall("Link"):
            rel = link.attrib.get("rel")
            if rel == "hcard":
                hcard_url = link.attrib.get("href")
            elif rel == "lrdd":
                lrdd_url = link.attrib.get("template")
        return {
            "subject": subject,
            "aliases": aliases,
            "hcard_url": hcard_url,
            "lrdd_url": lrdd_url,
        }
    except Exception:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    lrdd_link = hostmeta.find_link(rels="lrdd")
    if not lrdd_link:
        return None
    url = lrdd_link.template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        # Ensure settings_dirs is iterable
        if isinstance(settings_dirs, (str, bytes)):
            settings_dirs = [settings_dirs]
        file_names = []
        for dir_path in settings_dirs:
            if not os.path.isdir(dir_path):
                continue
            for fname in os.listdir(dir_path):
                if spec_option and not fname.endswith(spec_option):
                    continue
                file_names.append(os.path.join(dir_path, fname))
        return sorted(file_names)
    except Exception:
        return []

