@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content must be provided")

    # Load YAML content if it is a string, otherwise assume it is already a dict
    if isinstance(spec_content, str):
        try:
            data = yaml.safe_load(spec_content)
        except Exception as e:
            raise IRValidatorException(f"Error parsing YAML content: {e}")
    elif isinstance(spec_content, dict):
        data = spec_content
    else:
        raise IRValidatorException("spec_content must be a YAML string or a dict")

    if not isinstance(data, dict):
        raise IRValidatorException("Parsed YAML content is not a dictionary")

    # Determine required fields; subclasses may override REQUIRED_FIELDS
    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

    return data

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise IRValidatorException("yaml_file argument must be supplied")

    try:
        with open(yaml_file, "r") as f:
            data = yaml.safe_load(f)
    except FileNotFoundError as e:
        raise IRValidatorException(f"File not found: {yaml_file}") from e
    except Exception as e:
        raise IRValidatorException(f"Error loading YAML file: {e}") from e

    if data is None:
        raise IRValidatorException("YAML file is empty or could not be parsed")

    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a mapping at the top level")

    # Define the required fields for a valid IR file
    required_fields = ["name", "version", "data"]
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

    return data

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        def _merge_dicts(dest, src):
            for k, v in src.items():
                if k in dest and isinstance(dest[k], dict) and isinstance(v, dict):
                    _merge_dicts(dest[k], v)
                else:
                    dest[k] = v

        def _resolve(group_name, visited):
            if group_name in visited:
                raise RuntimeError(f"Circular include detected for group '{group_name}'")
            visited.add(group_name)
            group = parser_dict.get(group_name)
            if group is None:
                raise KeyError(f"Included group '{group_name}' not found in parser_dict")
            if not isinstance(group, dict):
                raise TypeError(f"Included group '{group_name}' must be a dict, got {type(group)}")
            # Resolve nested includes within the group
            if 'include' in group:
                inc = group.pop('include')
                if isinstance(inc, str):
                    inc = [inc]
                if not isinstance(inc, (list, tuple)):
                    raise TypeError(f"'include' value must be a string or list, got {type(inc)}")
                for inc_name in inc:
                    _resolve(inc_name, visited)
                    _merge_dicts(group, parser_dict[inc_name])
            visited.remove(group_name)

        # Resolve includes for all top-level groups
        for key, value in list(parser_dict.items()):
            if isinstance(value, dict) and 'include' in value:
                inc = value.pop('include')
                if isinstance(inc, str):
                    inc = [inc]
                if not isinstance(inc, (list, tuple)):
                    raise TypeError(f"'include' value must be a string or list, got {type(inc)}")
                for inc_name in inc:
                    _resolve(inc_name, set())
                    _merge_dicts(value, parser_dict[inc_name])
        return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    for arg in getattr(self, "args", []):
        # Skip non-option arguments
        if not isinstance(arg, _BaseOpt):
            continue

        # Determine the value: spec value takes precedence over the option's default
        if getattr(self, "spec", None) and arg.name in self.spec:
            value = self.spec[arg.name]
        else:
            value = arg.default

        # If no value is available, skip this argument
        if isinstance(value, NoDefault):
            continue

        # Handle nested dictionary options
        if isinstance(arg, DictOption):
            # If the value is a dict, merge it with defaults from the nested scheme
            if isinstance(value, dict):
                nested_defaults = {}
                if arg.scheme:
                    nested_defaults = arg.scheme.get_spec_defaults()
                # Merge nested defaults with the provided dict, giving precedence to the dict
                merged = {**nested_defaults, **value}
                defaults[arg.name] = merged
            else:
                # If the value is not a dict, use it directly
                defaults[arg.name] = value
        else:
            defaults[arg.name] = value

    return defaults

