    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Basic type checking
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Retrieve the mapping of deprecated arguments to their replacements.
    # If the attribute does not exist, assume no deprecations.
    deprecated_map = getattr(self, "deprecated_args", {})

    # Helper to report a deprecated argument
    def _report_deprecated(arg_name, source):
        replacement = deprecated_map.get(arg_name)
        if replacement:
            print(
                f"Warning: Argument '{arg_name}' from {source} is deprecated. "
                f"Use '{replacement}' instead."
            )
        else:
            print(
                f"Warning: Argument '{arg_name}' from {source} is deprecated, "
                f"but no replacement is defined."
            )

    # Check CLI arguments
    for arg in cli_args:
        if arg in deprecated_map:
            _report_deprecated(arg, "CLI")

    # Check answer file arguments
    for arg in answer_file_args:
        if arg in deprecated_map:
            _report_deprecated(arg, "answer file")
    # No return value needed; the method is used for side‑effects only.

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    # Retrieve the internal mapping of command names to option specs
    command_options = getattr(self, "_command_options", None)
    if command_options is None:
        raise AttributeError("The object does not contain a '_command_options' attribute")

    try:
        options = command_options[command_name]
    except KeyError:
        raise ValueError(f"Unknown command name: {command_name}") from None

    # Ensure we return a list (in case the stored value is another iterable)
    return list(options)

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    try:
        # Retrieve the command specifications dictionary
        command_specs = getattr(self, "_command_specs", {})
        if not isinstance(command_specs, dict):
            raise TypeError("Command specifications should be a dictionary")

        # Ensure the command exists
        if command_name not in command_specs:
            raise KeyError(f"Command '{command_name}' not found")

        arg_specs = command_specs[command_name]
        if not isinstance(arg_specs, dict):
            raise TypeError(f"Specifications for command '{command_name}' should be a dictionary")

        # Ensure the argument exists
        if argument_name not in arg_specs:
            raise KeyError(f"Argument '{argument_name}' not found for command '{command_name}'")

        # Return the specification
        return arg_specs[argument_name]
    except Exception as exc:
        # Wrap any exception in a ValueError with a clear message
        raise ValueError(f"Error retrieving option spec for command '{command_name}', argument '{argument_name}': {exc}") from exc

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent = []
    if isinstance(args, dict):
        for key, value in args.items():
            if value is None:
                silent.append(key)
    elif isinstance(args, (list, tuple)):
        for arg in args:
            if isinstance(arg, str) and arg.startswith('-'):
                silent.append(arg)
    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a mapping
    if args is None:
        raise TypeError("args must be a mapping of argument names to values")
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    # Retrieve the list of required arguments from the instance
    required = getattr(self, "required_args", None)
    if required is None:
        raise AttributeError("Instance does not define 'required_args' attribute")

    # Validate each required argument
    missing = []
    for name in required:
        if name not in args or args[name] is None:
            missing.append(name)

    if missing:
        missing_str = ", ".join(missing)
        raise ValueError(f"Missing required argument(s): {missing_str}")

    return True

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        # Basic type checks
        if not isinstance(command_name, str):
            raise TypeError("command_name must be a string")
        try:
            iter(options_spec)
        except TypeError:
            raise TypeError("options_spec must be an iterable")
        if not isinstance(args, dict):
            # If args is not a dict, try to convert to one if possible
            try:
                args = dict(args)
            except Exception:
                raise TypeError("args must be a mapping or convertible to one")

        required = []
        for opt in options_spec:
            # Retrieve option name
            if isinstance(opt, dict):
                name = opt.get('name')
                cond = opt.get('required_when')
            else:
                name = getattr(opt, 'name', None)
                cond = getattr(opt, 'required_when', None)

            if name is None:
                continue  # skip options without a name

            if cond is None:
                continue  # no conditional requirement

            # Evaluate condition
            matched = False
            if callable(cond):
                try:
                    matched = bool(cond(args))
                except Exception as exc:
                    raise ValueError(
                        f"Error evaluating required_when for option '{name}': {exc}"
                    ) from exc
            elif isinstance(cond, str):
                try:
                    matched = bool(eval(cond, {}, {'args': args}))
                except Exception as exc:
                    raise ValueError(
                        f"Error evaluating required_when expression for option "
                        f"'{name}': {exc}"
                    ) from exc
            elif isinstance(cond, bool):
                matched = cond
            else:
                raise TypeError(
                    f"Unsupported type for required_when in option '{name}': "
                    f"{type(cond).__name__}"
                )

            if matched:
                required.append(name)

        return required

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve argument definitions; adjust attribute name if necessary
    arg_defs = getattr(self, 'arg_definitions', {})
    for arg_name, value in args.items():
        # Skip if argument is not defined or has no choices
        arg_def = arg_defs.get(arg_name)
        if not arg_def:
            continue
        choices = arg_def.get('choices')
        if choices is None:
            continue

        # Skip validation for None values (e.g., optional arguments not provided)
        if value is None:
            continue

        # If the argument accepts multiple values, validate each element
        if isinstance(value, (list, tuple)):
            for v in value:
                if v not in choices:
                    raise ValueError(
                        f"Invalid value '{v}' for argument '{arg_name}'. "
                        f"Allowed choices: {choices}"
                    )
        else:
            if value not in choices:
                raise ValueError(
                    f"Invalid value '{value}' for argument '{arg_name}'. "
                    f"Allowed choices: {choices}"
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Determine the structure of args
    if isinstance(args, dict):
        try:
            min_val = args['min']
            max_val = args['max']
            value = args['value']
        except KeyError as e:
            raise ValueError(f"Missing required key: {e.args[0]}") from None
    elif isinstance(args, (list, tuple)):
        if len(args) != 3:
            raise ValueError("Expected 3 elements: min, max, value")
        min_val, max_val, value = args
    else:
        raise TypeError("args must be a dict or a tuple/list of length 3")

    # Ensure none of the values are None
    if min_val is None or max_val is None or value is None:
        raise ValueError("min, max, and value must not be None")

    # Validate that min <= max
    try:
        if min_val > max_val:
            raise ValueError(f"Minimum value {min_val} is greater than maximum value {max_val}")
    except TypeError:
        raise TypeError(f"Minimum and maximum values must be comparable: got {type(min_val)} and {type(max_val)}")

    # Validate that value is between min and max (inclusive)
    try:
        if not (min_val <= value <= max_val):
            raise ValueError(f"Value {value} is not between {min_val} and {max_val}")
    except TypeError:
        raise TypeError(f"Value {value} is not comparable with min/max types {type(min_val)} and {type(max_val)}")

    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dict")
    # Determine the parser function
    parser = spec_option.get('parser')
    if parser is None:
        t = spec_option.get('type')
        if t == 'int':
            parser = int
        elif t == 'float':
            parser = float
        elif t == 'list':
            sep = spec_option.get('sep', ',')
            parser = lambda s: s.split(sep)
        elif t == 'json':
            import json
            parser = json.loads
        else:
            parser = str
    # Create a simple namedtuple to hold the parsed value
    from collections import namedtuple
    Type = namedtuple(type_name, ['value'])
    def complex_type(value):
        try:
            parsed = parser(value)
        except Exception as exc:
            raise ValueError(f"Error parsing option '{option_name}' for subcommand '{subcommand}': {exc}")
        return Type(parsed)
    return complex_type

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Validate input
    if args is None:
        return {}, {}
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary, got %r" % type(args).__name__)

    control_args = {}
    nested_args = {}

    for key, value in args.items():
        # Only process string keys
        if not isinstance(key, str):
            continue

        # Determine if key is a control argument
        if key == "control" or key.startswith("control_"):
            control_args[key] = value
        # Custom arguments are treated as nested
        elif key == "custom" or key.startswith("custom_"):
            nested_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if vars_dict is None:
            raise ValueError("vars_dict must be a dictionary")
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

        if extra_vars is None:
            return vars_dict

        # If extra_vars is a dict, merge directly
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # If extra_vars is a list, merge each dict element
        if isinstance(extra_vars, list):
            for idx, item in enumerate(extra_vars):
                if isinstance(item, dict):
                    vars_dict.update(item)
                else:
                    raise TypeError(
                        f"Element at index {idx} in extra_vars is not a dict "
                        f"(got {type(item).__name__})"
                    )
            return vars_dict

        # Unsupported type for extra_vars
        raise TypeError(
            f"extra_vars must be a dict or list of dicts, got {type(extra_vars).__name__}"
        )

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Resolve playbook path relative to the workspace if not absolute
    if not os.path.isabs(playbook_path):
        playbook_path = os.path.join(ir_workspace.path, playbook_path)

    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Base command
    cmd = ["ansible-playbook", playbook_path]

    # Verbosity
    if verbose is not None:
        if not isinstance(verbose, int) or verbose < 0:
            raise ValueError("verbose must be a non‑negative integer")
        cmd.append("-" + "v" * verbose)
    else:
        # Default verbosity
        cmd.append("-v")

    # Extra vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        # Convert to JSON string for Ansible
        try:
            import json
            extra_str = json.dumps(extra_vars)
        except Exception as exc:
            raise ValueError(f"Failed to serialize extra_vars: {exc}") from exc
        cmd.extend(["--extra-vars", extra_str])

    # Additional ansible-playbook arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    cmd.append(f"--{key}")
            else:
                cmd.append(f"--{key}={value}")

    # Logging the command for debugging
    logger = logging.getLogger(__name__)
    logger.debug("Executing ansible-playbook command: %s", " ".join(cmd))

    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook executable not found") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

    if result.returncode != 0:
        error_msg = (
            f"ansible-playbook failed with return code {result.returncode}\n"
            f"stdout:\n{result.stdout}\n"
            f"stderr:\n{result.stderr}"
        )
        raise RuntimeError(error_msg)

    return result.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Helper conversion functions
    def _to_bool(val):
        if isinstance(val, bool):
            return val
        if isinstance(val, str):
            lowered = val.lower()
            if lowered in ("true", "1", "yes", "y"):
                return True
            if lowered in ("false", "0", "no", "n"):
                return False
        raise ValueError(f"Cannot convert {val!r} to bool")

    def _to_int(val):
        return int(val)

    def _to_float(val):
        return float(val)

    def _to_list(val):
        if isinstance(val, list):
            return val
        if isinstance(val, str):
            return [item.strip() for item in val.split(",") if item.strip()]
        raise ValueError(f"Cannot convert {val!r} to list")

    # Mapping of parser names to expected types for each argument
    # This can be extended as needed
    type_map = {
        "main": {"count": int, "threshold": float, "verbose": bool, "tags": list},
        "virsh": {"id": int, "force": bool},
        "ospd": {"port": int, "debug": bool, "hosts": list},
    }

    expected = type_map.get(parser_name, {})

    for key, val in list(values_dict.items()):
        target_type = expected.get(key)
        if target_type is None:
            # No explicit type mapping; try generic conversion
            if isinstance(val, str):
                lowered = val.lower()
                if lowered in ("true", "false"):
                    try:
                        values_dict[key] = _to_bool(val)
                        continue
                    except ValueError:
                        pass
                try:
                    values_dict[key] = int(val)
                    continue
                except ValueError:
                    pass
                try:
                    values_dict[key] = float(val)
                    continue
                except ValueError:
                    pass
            # leave as is
            continue

        try:
            if target_type is int:
                values_dict[key] = _to_int(val)
            elif target_type is float:
                values_dict[key] = _to_float(val)
            elif target_type is bool:
                values_dict[key] = _to_bool(val)
            elif target_type is list:
                values_dict[key] = _to_list(val)
            else:
                # Fallback: attempt direct cast
                values_dict[key] = target_type(val)
        except Exception as exc:
            # Log the error and keep the original value
            # In a real implementation you might use logging
            # Here we simply raise a ValueError with context
            raise ValueError(
                f"Error converting argument '{key}' with value '{val}' "
                f"to {target_type.__name__}"
            ) from exc
    # The function modifies values_dict in place; no return value needed.

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    spec_path = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.isfile(spec_path):
        # If plugin.json does not exist, return empty dict
        return {}

    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            spec = json.load(f)
    except (IOError, json.JSONDecodeError):
        # On read or parse error, return empty dict
        return {}

    return _flatten(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = "CONFIG_PATH"
    # Only set the variable if it is not already defined
    if env_var not in os.environ:
        # Ensure we have a config path to use
        config_path = getattr(self, "config_path", None)
        if config_path is None:
            raise ValueError("self.config_path is not set; cannot inject environment variable")
        # Convert to string if it is a Path-like object
        try:
            os.environ[env_var] = str(config_path)
        except Exception as exc:
            # Log the error and re‑raise to make debugging easier
            _log.exception("Failed to set environment variable %s: %s", env_var, exc)
            raise

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if path is None or root is None:
        raise ValueError("path and root must be non-None")
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)
    if not norm_root:
        raise ValueError("root must not be empty")
    try:
        common = os.path.commonpath([norm_path, norm_root])
    except ValueError:
        raise ValueError(f"Path '{path}' and root '{root}' are on different drives")
    if common != norm_root:
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    rel = os.path.relpath(norm_path, norm_root)
    return '' if rel == '.' else rel
